\copy ( WITH t AS ( SELECT a.sent_on::text||'|'||COALESCE(a.sender_name,'')||'|'||COALESCE(a.division,'')||'|'||COALESCE(a.subject,'') AS key, min(a.sent_time) AS tm FROM public.aca_sms_messages a GROUP BY 1 ) SELECT s.보낸사람, COALESCE(NULLIF(s.division,''),'(미상)') AS 발송관, s.전송일::text, s.요일, substr(COALESCE(t.tm,''),1,5) AS 전송시각, COALESCE(s.강좌, s.제목) AS 강좌, s.과목, s.유형, s.발송성격, COALESCE(s.강사,'(미기재)') AS 강사, s.강사수, s.학년, s.학교, s.대상수, s.금액, s."금액_배분", (row_number() OVER (PARTITION BY s.발송키 ORDER BY s.강사 NULLS FIRST, s.id) = 1)::int AS 대표행, extract(month FROM s.전송일)::int||'월' AS 월, s.발송키 FROM public.send_analysis_all s LEFT JOIN t ON t.key = s.발송키 WHERE s.출처='ACA' ORDER BY s.전송일, t.tm, s.발송키, s.강사 NULLS FIRST ) TO STDOUT WITH (FORMAT csv, HEADER true)
